    vector<string> frutas;
    frutas.push_back("manzana");
    frutas.push_back("pera");
    cout << frutas[0] << endl;
    cout << frutas.size() << endl;
    for (string f : frutas) {
        cout << "- " << f << endl;
    }
    return 0;
}
